<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Bus; use App\Models\Schedule; use Illuminate\Http\Request;
class ScheduleController extends Controller { public function index(){return view('admin.schedules.index',['schedules'=>Schedule::with('bus')->latest()->paginate(10)]);} public function create(){return view('admin.schedules.form',['schedule'=>new Schedule,'buses'=>Bus::orderBy('name')->get()]);} public function store(Request $r){Schedule::create($this->data($r));return redirect()->route('admin.schedules.index')->with('success','Jadwal berhasil ditambahkan.');} public function edit(Schedule $schedule){return view('admin.schedules.form',['schedule'=>$schedule,'buses'=>Bus::orderBy('name')->get()]);} public function update(Request $r,Schedule $schedule){$schedule->update($this->data($r));return redirect()->route('admin.schedules.index')->with('success','Jadwal diperbarui.');} public function destroy(Schedule $schedule){$schedule->delete();return back()->with('success','Jadwal dihapus.');} private function data(Request $r){return $r->validate(['bus_id'=>'required|exists:buses,id','day_type'=>'required|max:50','start_time'=>'required','end_time'=>'required|after:start_time','headway_minutes'=>'nullable|integer|min:1']);} }
